    start_of_window=DATETIME('now', 'start of month', '-6 months')
).Customers.WHERE(
    (join_date >= start_of_window) & (join_date < start_of_current_month)
).CALCULATE(
    signup_month=JOIN_STRINGS('-', YEAR(join_date), MONTH(join_date))
).PARTITION(
    name="monthly_signups", by=signup_month
).CALCULATE(
    month=signup_month,
    PMCS=COUNT(Customers),
