    ),
    PMSR=DEFAULT_TO(SUM(
        Sales.WHERE(
            (YEAR(salesperson.hire_date) >= 2022) & (YEAR(salesperson.hire_date) <= 2023)
        ).sale_price
    ), 0.0)
).ORDER_BY(month.ASC())

monthly_sales_metrics = Dealership.CALCULATE(
    # Define the time window: the start of 6 months ago and the start of the current month.
    six_months_ago_start=DATETIME('now', 'start of month', '-6 months'),
    current_month_start=DATETIME('now', 'start of month')
).CALCULATE(
    # Create a scaffold of all unique months within the defined time window.
    # This assumes at least one sale occurred globally in each month of the window.
    month_scaffold=Sales.CALCULATE(
        sale_month=DATETIME(sale_date, 'start of month')
    ).WHERE(
        (sale_month >= six_months_ago_start) & (sale_month < current_month_start)
    ).PARTITION(name='unique_months', by=sale_month).CALCULATE(
        month=sale_month
    ),
    # Pre-filter sales to include only those from salespersons hired in 2022-2023
    # and within the specified date range.
    target_sales=Salespersons.WHERE(
        (YEAR(hire_date) >= 2022) & (YEAR(hire_date) <= 2023)
    ).sales_made.WHERE(
        (sale_date >= six_months_ago_start) & (sale_date < current_month_start)
    )
).month_scaffold.CALCULATE(
    # For each month in the scaffold, filter the target sales to match the current month.
    sales_for_month=target_sales.WHERE(DATETIME(sale_date, 'start of month') == month)
).CALCULATE(
    # Calculate the final metrics for each month.
    month=month,
    PMSPS=COUNT(sales_for_month),
    PMSR=DEFAULT_TO(SUM(sales_for_month.sale_price), 0.0)
).ORDER_BY(month.ASC())

