    valid_outcomes=Outcomes.WHERE(PRESENT(day7_pasi_score) & PRESENT(day100_pasi_score))
).CALCULATE(
    avg_pasi_d7=AVG(valid_outcomes.day7_pasi_score),
    avg_pasi_d100=AVG(valid_outcomes.day100_pasi_score)
).CALCULATE(
    d7d100pir_percentage=((avg_pasi_d100 - avg_pasi_d7) / avg_pasi_d7) * 100.0
)

